def update_loss_streak_and_check(db, player_id, hand_outcome, current_balance):
    state = db_query('SELECT * FROM session_state WHERE player_id = ? AND game_type = ?', (player_id, 'blackjack')).fetchone()
    if not state:
        db_execute('INSERT INTO session_state (player_id, game_type, consecutive_losses, session_start_points, session_started_at, last_activity) VALUES (?, ?, 0, ?, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)', (player_id, 'blackjack', current_balance))
        state = {'consecutive_losses': 0, 'session_start_points': current_balance}
    if hand_outcome in ('done_loss', 'done_bust'):
        new_streak = state['consecutive_losses'] + 1
    else:
        new_streak = 0
    db_execute('UPDATE session_state SET consecutive_losses = ?, last_activity = CURRENT_TIMESTAMP WHERE player_id = ? AND game_type = ?', (new_streak, player_id, 'blackjack'))
    show_loss_streak_modal = (new_streak >= 20)
    net_loss = state['session_start_points'] - current_balance
    show_net_loss_modal = (net_loss >= 5 * state['session_start_points'])
    return {'show_loss_streak_modal': show_loss_streak_modal, 'show_net_loss_modal': show_net_loss_modal, 'consecutive_losses': new_streak, 'net_loss': net_loss}
